<template>
  <section class="attendance-overview">
    <el-collapse v-model="expandedSections"><el-collapse-item v-if="!admin" name="clock" title="打卡与请假">
    <template v-if="!admin">
      <header class="attendance-heading"><h3>打卡与请假</h3><div><AttendanceRulesPopover /><el-button type="primary" :disabled="!desktop||!today.can_check_in||clockSaving||todayLoading" @click="openClock('in')">上班打卡{{today.segment_count===2?`（第${today.next_segment+1}段）`:''}}</el-button><el-button type="primary" :disabled="!desktop||!clockRecord||!!clockRecord.check_out||clockSaving||todayLoading" :loading="clockSaving" @click="openClock('out')">下班打卡</el-button><DelayStartApplication @saved="refresh" /><el-button @click="leaveVisible=true">请假</el-button><el-button @click="refresh">刷新</el-button></div></header>
      <el-alert v-if="todayError" :title="todayError" type="error" :closable="false" />
      <el-alert v-else-if="!todayLoading&&desktop&&today.shift&&!today.record" title="今日尚未上班打卡，请点击上班打卡，阅读早餐提示后完成打卡。" type="warning" :closable="false" />
      <el-descriptions :column="2" border v-loading="todayLoading"><el-descriptions-item label="今日班次">{{today.shift?`${today.shift.label} · ${today.shift.periods.join(' / ')}`:'今日休息或尚未安排班次'}}</el-descriptions-item><el-descriptions-item label="上班打卡">{{formatBusinessDateTime(today.record?.check_in)}}</el-descriptions-item><el-descriptions-item label="下班打卡">{{formatBusinessDateTime(today.record?.check_out)}}</el-descriptions-item><el-descriptions-item label="今日请假"><template v-if="today.leaves?.length"><p v-for="(item,index) in today.leaves" :key="index">{{formatBusinessDateTime(item.start_at)}} 至 {{formatBusinessDateTime(item.end_at)}} · {{durationLabel(item.minutes)}} · {{item.reason}}</p></template><span v-else>无</span></el-descriptions-item></el-descriptions>
      <p v-if="today.pending_previous" class="attendance-note">尚有 {{today.pending_previous.day}} 的上班记录未签退，本次下班打卡将归到该记录。</p>
      <p class="attendance-note">上下班均须本人在电脑端点击打卡；登录系统不自动打卡。居家晚班每天按白天、晚间分两段打卡；手机端不记录上下班打卡。班次开始后 10 分钟内不算迟到，超过后仅累计超出部分。下班打卡入库成功后才显示成功。请假支持电脑和手机。</p>
      <div class="attendance-approval">请假审批 <el-tag type="info">待开发</el-tag></div>
      <div v-if="today.sessions?.length>1" class="attendance-sessions"><p v-for="item in today.sessions" :key="item.id">{{item.shift?.overtime_only?'公司要求居家加班':`第${(item.segment||0)+1}段`}}：{{formatBusinessDateTime(item.check_in)}} 至 {{formatBusinessDateTime(item.check_out)}}</p></div>
      <AttendanceLeaveDialog v-model="leaveVisible" @saved="refresh" />
      <AttendanceClockDialog v-model="clockVisible" :mode="clockMode" :record="clockRecord" :segment="today.next_segment||0" />
    </template>
    </el-collapse-item><el-collapse-item name="statistics" title="考勤与加班统计"><header class="attendance-heading"><h3>{{admin?'考勤管理':'我的考勤统计'}}</h3><AttendanceRulesPopover /><ShiftPeriodControls action="统计" v-model:mode="mode" :value="periodValue" :disabled="loading" @update:value="setPeriod" /></header>
    <div v-if="admin" class="attendance-filters"><el-input v-model="keyword" placeholder="搜索姓名或账号" clearable aria-label="考勤人员搜索" @keyup.enter="query" @clear="query" /><el-select v-model="department" clearable filterable placeholder="全部部门" aria-label="考勤部门" @change="query"><el-option v-for="item in report.departments||[]" :key="item.id" :value="String(item.id)" :label="item.name" /></el-select><el-button @click="query">查询</el-button><el-button @click="reset">重置</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <p class="attendance-note">{{report.start}} 至 {{report.end}} · {{report.note||'迟到与加班按班次统计；加班时长已扣除午休 12:00–13:30 及其他班间休息。'}}</p>
    <div class="attendance-totals" v-loading="loading"><div><span>迟到次数</span><strong>{{report.totals?.late_count||0}} 次</strong></div><div><span>迟到累计</span><strong>{{durationLabel(report.totals?.late_minutes)}}</strong></div><div><span>加班累计</span><strong>{{durationLabel(report.totals?.overtime_minutes)}}</strong></div><div><span>中午加班</span><strong>{{durationLabel(report.totals?.lunch_overtime_minutes)}}</strong></div><div><span>违纪次数</span><strong>{{report.totals?.violation_count||0}} 次</strong></div><div><span>加班抵扣</span><strong>{{durationLabel((report.totals?.breakfast_deduction_minutes||0)+(report.totals?.dinner_deduction_minutes||0)+(report.totals?.invalid_deduction_minutes||0))}}</strong></div><div><span>请假累计</span><strong>{{durationLabel(report.totals?.leave_minutes)}}</strong></div></div>
    <p v-if="!admin&&report.annual_leave" class="attendance-note">{{report.annual_leave.annual_leave_year}}年年假额度：{{report.annual_leave.annual_leave_days==null?'待填写入职时间':`${report.annual_leave.annual_leave_days}天`}}<template v-if="report.annual_leave.annual_leave_next_increase">；下次增加：{{annualLeaveDateLabel(report.annual_leave.annual_leave_next_increase)}}</template>（额度未扣除已休年假）</p>
    <p class="attendance-note">请假累计 = 申请请假 {{durationLabel(report.totals?.requested_leave_minutes)}} + 迟到折算请假 {{durationLabel(report.totals?.late_leave_minutes)}}。迟到折算单独保留来源，不重复生成请假申请；不追责次数仍计入请假。补班、调休和年终奖挂钩详情请展开下方对应区域。</p><div class="attendance-month-balances"><p v-for="balance in report.monthly_balances||[]" :key="`${balance.user_id}:${balance.month}`"><template v-if="admin">{{balance.name}} · </template>{{balance.month}} 月累计加班：原额 {{durationLabel(balance.raw_minutes)}} − 抵扣 {{durationLabel(balance.deduction_minutes)}} = {{durationLabel(balance.overtime_minutes)}}<span v-if="balance.remaining_deduction_minutes">；待抵扣 {{durationLabel(balance.remaining_deduction_minutes)}}（仅限本月）</span></p></div>
    <el-tabs v-model="detailsTab"><el-tab-pane v-if="admin" name="people" label="人员累计"><el-table :data="report.people||[]" border v-loading="loading"><el-table-column prop="name" label="姓名" min-width="120" /><el-table-column prop="department" label="部门" min-width="150" /><el-table-column prop="late_count" label="迟到次数" width="100" /><el-table-column label="迟到累计" min-width="130"><template #default="{row}">{{durationLabel(row.late_minutes)}}</template></el-table-column><el-table-column label="加班累计" min-width="130"><template #default="{row}">{{durationLabel(row.overtime_minutes)}}</template></el-table-column><el-table-column label="入职时间" min-width="150"><template #default="{row}">{{annualLeaveDateLabel(row.hire_date)}}</template></el-table-column><el-table-column label="年假额度" min-width="140"><template #default="{row}">{{row.annual_leave_days==null?'待填写入职时间':`${row.annual_leave_days}天`}}</template></el-table-column><el-table-column label="下次年假增加" min-width="155"><template #default="{row}">{{annualLeaveDateLabel(row.annual_leave_next_increase)}}</template></el-table-column><el-table-column label="请假累计" min-width="130"><template #default="{row}">{{durationLabel(row.leave_minutes)}}</template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane name="records" label="每日明细"><el-table :data="report.records||[]" border v-loading="loading"><el-table-column prop="day" label="日期" width="110" /><el-table-column v-if="admin" prop="name" label="姓名" min-width="100" /><el-table-column label="班次" min-width="120"><template #default="{row}">{{row.shift?.label||'-'}}<el-tag v-if="row.leave_minutes" size="small" type="warning">请假 {{durationLabel(row.leave_minutes)}}</el-tag></template></el-table-column><el-table-column label="上班打卡" min-width="175"><template #default="{row}">{{formatBusinessDateTime(row.check_in)}}</template></el-table-column><el-table-column label="下班打卡" min-width="175"><template #default="{row}">{{formatBusinessDateTime(row.check_out)}}</template></el-table-column><el-table-column label="本次迟到" min-width="120"><template #default="{row}">{{durationLabel(row.late_minutes)}}</template></el-table-column><el-table-column label="本次加班" min-width="120"><template #default="{row}">{{row.check_out?durationLabel(row.overtime_minutes):'待下班打卡'}}</template></el-table-column><el-table-column prop="violation_count" label="违纪次数" width="100" /><el-table-column label="已扣午休" min-width="110"><template #default="{row}">{{row.check_out?durationLabel(row.lunch_deducted_minutes):'-'}}</template></el-table-column><el-table-column label="本日请假" min-width="120"><template #default="{row}">{{durationLabel(row.leave_minutes)}}</template></el-table-column><el-table-column label="详情" fixed="right" width="100"><template #default="{row}"><el-popover trigger="click" placement="left" :width="760"><template #reference><el-button link type="primary">查看详情</el-button></template><div class="attendance-detail"><h4>{{row.name}} · {{row.day}} 考勤详情</h4><el-descriptions :column="2" border size="small"><el-descriptions-item label="班次时段" :span="2">{{row.shift?.periods?.join(' / ')||'-'}}</el-descriptions-item><el-descriptions-item label="迟到">{{durationLabel(row.late_minutes)}}</el-descriptions-item><el-descriptions-item label="加班净额">{{durationLabel(row.overtime_minutes)}}</el-descriptions-item><el-descriptions-item v-if="row.raw_overtime_minutes!=null" label="加班原额">{{durationLabel(row.raw_overtime_minutes)}}</el-descriptions-item><el-descriptions-item label="违纪次数">{{row.violation_count||0}} 次</el-descriptions-item></el-descriptions><template v-if="row.sessions?.length"><article v-for="session in row.sessions" :key="session.id"><strong>{{session.shift?.overtime_only?'公司要求居家加班':`第${(session.segment||0)+1}段`}}</strong><p>{{formatBusinessDateTime(session.check_in)}} 至 {{formatBusinessDateTime(session.check_out)}}</p><p v-for="(detail,index) in session.deduction_details" :key="index">{{detail.reason}}：{{detail.kind==='deduction'?'-':'+'}}{{durationLabel(detail.minutes)}}</p><p>原额 {{durationLabel(session.raw_overtime_minutes)}} − 早餐 {{durationLabel(session.breakfast_deduction_minutes)}} − 晚餐 {{durationLabel(session.dinner_deduction_minutes)}} − 无效时间 {{durationLabel(session.invalid_deduction_minutes)}} = 净额 {{durationLabel(session.overtime_minutes)}}<span v-if="session.overtime_minutes<0">（从当月累计加班继续抵扣）</span></p></article></template><p v-if="row.lunch_reported_minutes">中午加班申报 {{durationLabel(row.lunch_reported_minutes)}}，计入 {{durationLabel(row.lunch_overtime_minutes)}}；原扣午休 {{durationLabel(row.lunch_original_deducted_minutes)}} − 计回 {{durationLabel(row.lunch_overtime_minutes)}} = 实扣 {{durationLabel(row.lunch_deducted_minutes)}}。已声明中午确实工作，且未顺延下午上班时间。</p><p v-for="(delay,index) in row.delay_start_requests||[]" :key="`delay:${index}`">延迟上班申请：预计 {{formatBusinessDateTime(delay.requested_start)}}；事由：{{delay.reason}}；申请时间 {{formatBusinessDateTime(delay.created_at)}}。</p><p v-for="event in row.late_leave_events||[]" :key="event.id">迟到折算请假：{{durationLabel(event.minutes)}}；来源打卡 {{event.clock_id}}；本月第{{event.ordinal}}次，{{event.bonus_linked?'年终奖挂钩（待开发）':'不追责'}}。</p><p v-for="item in row.leaves" :key="item.id">请假：{{formatBusinessDateTime(item.start_at)}} 至 {{formatBusinessDateTime(item.end_at)}} · {{durationLabel(item.minutes)}} · {{item.reason}}</p></div></el-popover></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="report.total||0" :page-size="50" layout="total, prev, pager, next" @current-change="loadReport" /></el-tab-pane>
      <el-tab-pane name="leave" label="请假明细"><el-table :data="report.leaves||[]" border v-loading="loading"><el-table-column v-if="admin" prop="name" label="姓名" width="120" /><el-table-column label="来源" min-width="130"><template #default="{row}"><el-tag :type="row.source==='lateness'?'warning':'info'">{{row.source_label||'申请请假'}}</el-tag></template></el-table-column><el-table-column label="开始时间" min-width="175"><template #default="{row}">{{formatBusinessDateTime(row.start_at)}}</template></el-table-column><el-table-column label="结束时间" min-width="175"><template #default="{row}">{{formatBusinessDateTime(row.end_at)}}</template></el-table-column><el-table-column label="本周期时长" min-width="130"><template #default="{row}">{{durationLabel(row.minutes)}}</template></el-table-column><el-table-column prop="reason" label="原因" min-width="220" show-overflow-tooltip /></el-table></el-tab-pane></el-tabs>
    <div v-if="admin" class="attendance-approval">请假审批 <el-tag type="info">待开发</el-tag></div>
    </el-collapse-item><el-collapse-item v-if="admin" name="home-office" title="居家办公申请"><HomeOfficePanel admin /></el-collapse-item><el-collapse-item name="policy" title="补班、调休与年终奖"><AttendancePolicyPanel v-if="expandedSections.includes('policy')" :admin="admin" /></el-collapse-item></el-collapse>
  </section>
</template>
<script setup>
import AttendancePolicyPanel from './AttendancePolicyPanel.vue'
import DelayStartApplication from './DelayStartApplication.vue'
import HomeOfficePanel from './HomeOfficePanel.vue'
import AttendanceRulesPopover from '@/components/common/AttendanceRulesPopover.vue'
import {annualLeaveDateLabel} from '@/utils/annualLeave'
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import {ElMessage} from 'element-plus'
import ShiftPeriodControls from '@/components/common/ShiftPeriodControls.vue'
import AttendanceLeaveDialog from './AttendanceLeaveDialog.vue'
import AttendanceClockDialog from './AttendanceClockDialog.vue'
import {getTodayAttendance,getAttendanceReport} from '@/api/attendance'
import {currentShiftWeek,currentShiftMonth,shiftWeek} from '@/utils/monthlyShift'
import {formatBusinessDateTime} from '@/utils/dateTime'
import {durationLabel} from '@/utils/attendance'
import {chatClientType} from '@/utils/chatDevice'
const props=defineProps({admin:Boolean})
const mode=ref('week'),week=ref(currentShiftWeek()),month=ref(currentShiftMonth()),page=ref(1),report=ref({}),loading=ref(false),error=ref(''),keyword=ref(''),department=ref(''),detailsTab=ref(props.admin?'people':'records')
const today=ref({}),todayLoading=ref(false),todayError=ref(''),clockSaving=ref(false),leaveVisible=ref(false),desktop=chatClientType(navigator)==='desktop'
const clockRecord=computed(()=>today.value.pending_previous||today.value.record)
const expandedSections=ref(props.admin?['statistics']:['clock']),clockVisible=ref(false),clockMode=ref('in')
function openClock(value){clockMode.value=value;clockVisible.value=true}
const periodValue=computed(()=>mode.value==='week'?week.value:month.value),periodKey=computed(()=>`${mode.value}:${periodValue.value}`)
let controller,sequence=0,timer,alive=true,todaySequence=0
function setPeriod(value){if(mode.value==='week')week.value=shiftWeek(value);else month.value=value}
function query(){clearTimeout(timer);page.value=1;loadReport()}
function reset(){keyword.value='';department.value='';query()}
async function loadReport(){controller?.abort();controller=new AbortController();const id=++sequence;loading.value=true;error.value='';try{const value=await getAttendanceReport({anchor:mode.value==='week'?week.value:`${month.value}-01`,period:mode.value,page:page.value,keyword:keyword.value,department:department.value},props.admin,{signal:controller.signal});if(alive&&id===sequence)report.value=value}catch(e){if(alive&&id===sequence&&e.code!=='ERR_CANCELED'){report.value={};error.value=e.detail||'读取考勤失败'}}finally{if(alive&&id===sequence)loading.value=false}}
async function loadToday(){if(props.admin)return;const id=++todaySequence;todayLoading.value=true;todayError.value='';try{const value=await getTodayAttendance();if(alive&&id===todaySequence)today.value=value}catch(e){if(alive&&id===todaySequence)todayError.value=e.detail||'读取打卡失败'}finally{if(alive&&id===todaySequence)todayLoading.value=false}}
function refresh(){loadToday();query()}

watch(periodKey,query);watch(keyword,value=>{clearTimeout(timer);if(!value)query();else timer=setTimeout(query,400)})
onMounted(()=>{refresh();window.addEventListener('focus',refresh);window.addEventListener('attendance-clock-changed',refresh);window.addEventListener('work-report-lunch-changed',refresh)})
onBeforeUnmount(()=>{alive=false;sequence++;todaySequence++;controller?.abort();clearTimeout(timer);window.removeEventListener('focus',refresh);window.removeEventListener('attendance-clock-changed',refresh);window.removeEventListener('work-report-lunch-changed',refresh)})
</script>
<style scoped>.attendance-overview{margin-bottom:24px;min-width:0}.attendance-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:12px 0}.attendance-heading h3{margin:0}.attendance-heading>div{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.attendance-heading :deep(.el-button+.el-button){margin-left:0}.attendance-note{font-size:12px;line-height:1.8;color:#64748b}.attendance-approval{padding:12px 0;display:flex;gap:12px;align-items:center;color:#64748b}.attendance-totals{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:12px 0}.attendance-totals>div{border:1px solid #e2e8f0;border-radius:8px;padding:14px;background:#f8fafc;display:flex;flex-direction:column;gap:8px}.attendance-totals span{font-size:13px;color:#64748b}.attendance-totals strong{font-size:19px}.attendance-filters{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.attendance-filters .el-input,.attendance-filters .el-select{width:220px}.attendance-detail{max-height:560px;overflow-y:auto;overflow-wrap:anywhere}.el-pagination{margin-top:12px}@media(max-width:680px){.attendance-totals{grid-template-columns:repeat(2,minmax(0,1fr))}.attendance-overview :deep(.el-descriptions__label){width:85px}}</style>
